import { randomUUID } from "node:crypto";
import {
  NotFoundError,
  Project,
  ProjectRepository,
  Task,
  TaskFilter,
  TaskRepository,
  TaskStatus,
  User,
  UserRepository,
  ValidationError,
  markDone,
} from "../domain/model";

function requireText(value: unknown, field: string): string {
  if (typeof value !== "string" || value.trim() === "") {
    throw new ValidationError(`${field} is required`);
  }
  return value.trim();
}

export interface CreateTaskInput {
  title: unknown;
  description?: unknown;
  dueDate?: unknown;
  status?: TaskStatus;
  assigneeId?: string | null;
}

export class TaskManagementService {
  constructor(
    private readonly users: UserRepository,
    private readonly projects: ProjectRepository,
    private readonly tasks: TaskRepository,
  ) {}

  createUser(name: unknown): User {
    const user: User = { id: randomUUID(), name: requireText(name, "name") };
    this.users.save(user);
    return user;
  }

  createProject(name: unknown): Project {
    const project: Project = { id: randomUUID(), name: requireText(name, "name") };
    this.projects.save(project);
    return project;
  }

  getProject(id: string): Project {
    return this.requireProject(id);
  }

  addTask(projectId: string, input: CreateTaskInput): Task {
    this.requireProject(projectId);
    const title = requireText(input.title, "title");
    if (input.description !== undefined && typeof input.description !== "string") {
      throw new ValidationError("description must be a string");
    }
    let dueDate: Date | null = null;
    if (input.dueDate !== undefined && input.dueDate !== null) {
      dueDate = typeof input.dueDate === "string" ? new Date(input.dueDate) : new Date(NaN);
      if (Number.isNaN(dueDate.getTime())) {
        throw new ValidationError("dueDate must be a valid date string");
      }
    }
    const assigneeId = input.assigneeId ?? null;
    if (assigneeId !== null) this.requireUser(assigneeId);

    const task: Task = {
      id: randomUUID(),
      projectId,
      title,
      description: input.description ?? "",
      dueDate,
      status: input.status ?? "todo",
      assigneeId,
    };
    this.tasks.save(task);
    return task;
  }

  assignTask(taskId: string, assigneeId: unknown): Task {
    const task = this.requireTask(taskId);
    const id = requireText(assigneeId, "assigneeId");
    this.requireUser(id);
    const updated: Task = { ...task, assigneeId: id };
    this.tasks.save(updated);
    return updated;
  }

  listTasks(projectId: string, filter: TaskFilter): Task[] {
    this.requireProject(projectId);
    return this.tasks.findByProject(projectId, filter);
  }

  completeTask(taskId: string): Task {
    const updated = markDone(this.requireTask(taskId));
    this.tasks.save(updated);
    return updated;
  }

  private requireUser(id: string): User {
    const user = this.users.findById(id);
    if (!user) throw new ValidationError(`Assignee ${id} does not exist`);
    return user;
  }

  private requireProject(id: string): Project {
    const project = this.projects.findById(id);
    if (!project) throw new NotFoundError(`Project ${id} not found`);
    return project;
  }

  private requireTask(id: string): Task {
    const task = this.tasks.findById(id);
    if (!task) throw new NotFoundError(`Task ${id} not found`);
    return task;
  }
}

